mapper.delete:
UPDATE t_sys_org SET delete_flag = 1 where delete_flag = 0
AND id IN

    #{id}

mapper.update:
UPDATE t_sys_org
SET t_sys_org.left_num = t_sys_org.left_num - (
#{rightNum} - #{leftNum} + 1
)
where t_sys_org.left_num > #{leftNum} AND t_sys_org.delete_flag = 0;

UPDATE t_sys_org
SET t_sys_org.right_num = t_sys_org.right_num - (
#{rightNum} - #{leftNum} + 1
)
where t_sys_org.right_num > #{rightNum} AND t_sys_org.delete_flag = 0;

UPDATE t_sys_org
SET t_sys_org.left_num  = -t_sys_org.left_num,
    t_sys_org.right_num= -t_sys_org.right_num,
    t_sys_org.node_level= -t_sys_org.node_level
where t_sys_org.left_num >= #{leftNum}
  and t_sys_org.right_num <= #{rightNum}
  and t_sys_org.delete_flag = 0
;

UPDATE t_sys_org
SET t_sys_org.left_num = t_sys_org.left_num - (#{rightNum} - #{leftNum} + 1)
where t_sys_org.left_num > #{leftNum} AND t_sys_org.delete_flag = 0;

UPDATE t_sys_org
SET t_sys_org.right_num = t_sys_org.right_num - (#{rightNum} - #{leftNum} + 1)
where t_sys_org.right_num > #{rightNum} AND t_sys_org.delete_flag = 0;

UPDATE t_sys_org
SET t_sys_org.left_num = t_sys_org.left_num + (#{rightNum} - #{leftNum} + 1)
where t_sys_org.left_num > #{pRightNum} AND t_sys_org.delete_flag = 0;

UPDATE t_sys_org
SET t_sys_org.right_num = t_sys_org.right_num + (#{rightNum} - #{leftNum} + 1)
where t_sys_org.right_num >= #{pRightNum} AND t_sys_org.delete_flag = 0;

UPDATE t_sys_org
SET t_sys_org.node_level = t_sys_org.node_level + (#{nodeLevel} - #{pNodeLevel} - 1)
where t_sys_org.node_level < 0 AND t_sys_org.delete_flag = 0;
